('Katja Grace', 'AI Impacts', NULL, '2015-04-06', 'year', NULL, NULL, 'https://web.archive.org/web/20150406054042/https://aiimpacts.org/about/ https://web.archive.org/web/20200819054836/https://aiimpacts.org/about/', 'All five supplied snapshots (April and August 2015; March, April and May 2016) explicitly state that AIimpacts.org is written and maintained by Katja Grace and Paul Christiano. Formal title, joining date and employment type are unspecified. Start date records earliest supplied observation, not an exact joining date. June and July 2017 continue to describe writing and maintenance; October 2017 says Katja runs AI Impacts. No formal title is specified.', 'AGI organization', 'strategy', NULL, 'AI safety'), /*Last checked Wayback snapshot is from 2020-08-19*/
('Paul Christiano', 'AI Impacts', NULL, '2015-04-06', 'year', '2016-05-01', 'year', 'https://web.archive.org/web/20150406054042/https://aiimpacts.org/about/ https://web.archive.org/web/20160501100523/https://aiimpacts.org/about/ https://web.archive.org/web/20170618202357/https://aiimpacts.org/about/ https://web.archive.org/web/20171026011846/https://aiimpacts.org/about/', 'All five supplied snapshots (April and August 2015; March, April and May 2016) explicitly state that AIimpacts.org is written and maintained by Katja Grace and Paul Christiano. Formal title, joining date and employment type are unspecified. Start date records earliest supplied observation, not an exact joining date. Last listed actively May 1, 2016; absent from the June 18, 2017 active description, and explicitly listed as a past contributor October 26, 2017.', 'AGI organization', 'strategy', NULL, 'AI safety'), /*Closed*/
